package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsFoodAge {
 @GameTest(template="empty") public static void fractionalFreshnessUsesIntegerCompatibleBuildingStorage(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){var material=f.city.housing.market.get("minecraft:oak_planks");material.freshness.add(8,0);material.freshness.advance(3*24000L,FoodAge.period(0));var json=CityRegistry.export(f.city);CityMaintenance.exact(json.get("housing"));var restored=new CityData.City(f.city.id,f.city.owner,f.city.name,f.city.dimension,f.city.bounds);restored.residents.addAll(f.city.residents);CityRegistry.read(restored,json);h.assertTrue(restored.housing.market.get("minecraft:oak_planks").freshness.groups.getFirst().age==FoodAge.SCALE*3/8,"Fractional freshness round-trips through strict integer city registry");}h.succeed();}
 @GameTest(template="empty") public static void groupedBreadSpoilageMatchesConfirmedThirtyDayTable(GameTestHelper h){var a=new FoodAge.State();a.add(64,0);int spoiled=a.advance(30*24000L,FoodAge.period(1));h.assertTrue(spoiled==22&&a.quantity()==42,"64bread decays22 units across30days; not all64 at once");var wheat=new FoodAge.State();wheat.add(64,0);h.assertTrue(wheat.advance(30*24000L,FoodAge.period(0))==8,"64wheat loses8 in30days");h.succeed();}
 @GameTest(template="empty") public static void transferPreservesMeanFreshnessAndCookingRefreshesOnlyProduct(GameTestHelper h){var from=new RuralRules.Stock();var to=new RuralRules.Stock();RuralRules.put(List.of(from),false,8);from.ages[0].advance(4*24000L,FoodAge.period(0));FoodMoves.move(List.of(from),List.of(to),0,4);h.assertTrue(Math.abs(to.ages[0].groups.getFirst().age/(double)FoodAge.SCALE-.5)<1e-8&&from.wheat==4,"Taking or moving food does not reset age");RuralRules.put(List.of(to),false,4);h.assertTrue(Math.abs(to.ages[0].groups.getFirst().age/(double)FoodAge.SCALE-.25)<1e-8,"Combining fresh and old food averages the real quantities");RuralRules.cook(List.of(to),2,2,false);h.assertTrue(to.bread==2&&to.ages[1].groups.getFirst().age==0&&to.wheat==6,"Cooking consumes old wheat and creates fresh product");h.succeed();}
 @GameTest(template="empty") public static void lotMovesAndReloadDoNotRenewExpiryOrDuplicateCost(GameTestHelper h){var source=new TradeRules.Lot();source.add(64,6400);source.freshness.advance(24000,FoodAge.period(1));var to=new TradeRules.Lot();TradeRules.move(source,to,16);var copy=CityEconomy.JSON.fromJson(CityEconomy.JSON.toJson(to),TradeRules.Lot.class);h.assertTrue(copy.count==16&&copy.cents==1600&&Math.abs(copy.freshness.groups.getFirst().age/(double)FoodAge.SCALE-.8)<1e-8,"Goods and cost and decay state survive movement and reload");var loss=new FoodDecay.Loss();int spoiled=FoodDecay.lot(copy,1,2*24000L,loss);h.assertTrue(spoiled>0&&loss.costCents==spoiled*100&&copy.cents==(16-spoiled)*100,"Spoiled inventory writes off cost once without cash transfer");h.succeed();}
}
